  by={h['number']:h for h in r['horses']};n=r['notes'];parts.append('<article class="race" id="'+r['race_uid']+'"><header class="race-head"><p class="eyebrow">'+r['venue']+' '+str(r['race'])+'R</p><h2>'+E(r['name'])+'</h2><p>確定 '+E(' → '.join(str(x)+' '+by[x]['name'] for x in r['top_three']))+'</p></header><div class="race-body"><h3>'+E(n[0])+'</h3><p><b>当たり・外れと採否の理由</b><br>'+E(n[1])+'</p><p class="decision"><b>事前に可能だった比較／次回</b><br>'+E(n[2])+'</p><details><summary>固定した勝つ／圏内候補と展開</summary>'+''.join('<p>'+E(r['original_analysis'][k])+'</p>' for k in ['win_view','place_view','pace','alternate','decision'])+'</details>')
